def canon(x):return json.dumps(x,sort_keys=True,separators=(',',':'),ensure_ascii=True).encode()
def handle(e):
 if set(e)!={'operation','payload','scopeBinding'}:raise ValueError('Fixed runtime envelope required')
 op=e['operation'];p=e['payload'];network=e['scopeBinding'].get('network')
 if network not in ('regtest','mainnet') or not isinstance(p,dict) or p.get('network')!=network:raise ValueError('Explicit chain binding mismatch')
 if op not in ('pin-export-v4','pin-candidates-v5','pin-handoff-v5','subset-export-v5','subset-verify-v5'):raise ValueError('Unknown fixed operation')
 # Validate exactly once, before any runtime/reference imports or construction.
 ctx=p.get('context') if op.startswith('subset-') else {k:p.get(k) for k in ('publicStateJson','manifest')}
 if not isinstance(ctx,dict) or not isinstance(ctx.get('publicStateJson'),str):raise ValueError('Public state context required')
 raw=ctx['publicStateJson']
 if len(raw.encode())>500000:raise ValueError('Oversized public state')
 if hashlib.sha256(VALIDATOR.encode()).hexdigest()!=VALIDATOR_HASH:raise ValueError('Validator identity mismatch')
 ns={'__name__':'fixed_publicstate','__file__':'<fixed_publicstate>'};exec(compile(VALIDATOR,'<fixed_publicstate>','exec'),ns)
 checked=ns['validate_public_state'](json.loads(raw))
 public_validation={**checked,'validatorSourceHash':VALIDATOR_HASH,'publicStateHash':hashlib.sha256(raw.encode()).hexdigest(),'contextHash':hashlib.sha256(canon(ctx)).hexdigest()}
 sys.path.insert(0,'/opt/qsb-validation');import runtime
 _,actual=runtime.bindings();expected=PIN if op=='pin-export-v4' else V5
 if actual!=expected:raise ValueError('Wrong immutable runtime')
 with contextlib.redirect_stdout(io.StringIO()):
  if op=='pin-export-v4':
   if set(p)!={'publicStateJson','manifest','network'} or p['network']!=network:raise ValueError('Pin export envelope')
   result=runtime.reference(dict(publicStateJson=p['publicStateJson'],manifest=p['manifest'],action='export',stage='pinning'))
  elif op=='pin-handoff-v5':
   if p.get('network')!=network:raise ValueError('Regtest only')
   ns={'__name__':'fixed_handoff'};exec(compile(HANDOFF,'<fixed>','exec'),ns);result=ns['handle'](p)
  elif op=='pin-candidates-v5':
   if set(p)!={'publicStateJson','manifest','network','candidates'} or not isinstance(p['candidates'],list) or not 1<=len(p['candidates'])<=32:raise ValueError('Pin list envelope')
   parsed=[]
   for file in p['candidates']:
    if not isinstance(file,str) or len(file.encode())>=16384:raise ValueError('Candidate file')
    records=[v for v in re.split(r'(?=^sequence=)',file,flags=re.M) if v.strip()]
    if not records:raise ValueError('Empty candidate file')
    for record in records:
     seq=re.findall(r'^sequence=(\d+)\r?$',record,flags=re.M);lt=re.findall(r'^locktime=(\d+)\r?$',record,flags=re.M)
     if len(seq)!=1 or len(lt)!=1:raise ValueError('Ambiguous candidate')
     parsed.append({'sequence':int(seq[0]),'locktime':int(lt[0])})
   ns={'__name__':'fixed_candidates'};exec(compile(CANDIDATES,'<fixed>','exec'),ns);out=ns['handle']({**p,'candidates':parsed,'candidateFiles':p['candidates']});result={'runtimeHash':V5,'verdict':out['verdict']}
  else:
   action='export' if op=='subset-export-v5' else 'verify'
   if p.get('action')!=action or p.get('runtimeHash')!=V5 or p.get('request',{}).get('stage') not in ('round1','round2'):raise ValueError('Subset envelope')
   result=runtime.handle({k:v for k,v in p.items() if k!='network'})
 return {'format':'qsb-owned-runtime-result-v1','operation':op,'network':network,'runtimeHash':expected,'inputHash':hashlib.sha256(canon(e)).hexdigest(),'publicStateValidation':public_validation,'result':result}
